import{_ as a,c as r,o,al as t}from"./chunks/framework.D8UyiDWg.js";const f=JSON.parse('{"title":"DroneCAN ESCs","description":"","frontmatter":{},"headers":[],"relativePath":"en/dronecan/escs.md","filePath":"en/dronecan/escs.md"}'),n={name:"en/dronecan/escs.md"};function i(l,e,s,c,d,h){return o(),r("div",null,e[0]||(e[0]=[t('<h1 id="dronecan-escs" tabindex="-1">DroneCAN ESCs <a class="header-anchor" href="#dronecan-escs" aria-label="Permalink to &quot;DroneCAN ESCs&quot;">​</a></h1><p>PX4 supports DroneCAN compliant ESCs. For more information, see the following articles for specific hardware/firmware:</p><ul><li><a href="./sapog.html">PX4 Sapog ESC Firmware</a><ul><li><a href="./holybro_kotleta.html">Holybro Kotleta 20</a></li></ul></li><li><a href="./zubax_telega.html">Zubax Telega</a></li><li><a href="./../peripherals/vertiq.html">Vertiq</a> (larger modules)</li><li><a href="./../peripherals/vesc.html">VESC Project</a></li><li><a href="./raccoonlab_nodes.html">RaccoonLab Cyphal and DroneCAN PWM nodes</a></li></ul><h2 id="hardware-configuration" tabindex="-1">Hardware Configuration <a class="header-anchor" href="#hardware-configuration" aria-label="Permalink to &quot;Hardware Configuration&quot;">​</a></h2><p>General DroneCAN hardware configuration is covered in <a href="./../dronecan/#hardware-setup">DroneCAN &gt; Hardware Setup</a>.</p><p>DroneCAN ESCs should be on their own dedicated CAN interface(s) because ESC messages can saturate the bus and starve other nodes of bandwidth.</p><h2 id="px4-configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 Configuration&quot;">​</a></h2><p>DroneCAN peripherals are configured by following the procedure outlined in <a href="./../dronecan/">DroneCAN</a>.</p><p>In addition to the general setup, such as setting <code>UAVCAN_ENABLE</code> to <code>3</code>:</p><ul><li>Select the specific CAN interface(s) used for ESC data output using the <a href="./../advanced_config/parameter_reference.html#UAVCAN_ESC_IFACE">UAVCAN_ESC_IFACE</a> parameter (all that all interfaces are selected by default).</li><li>Configure the <a href="./../config/actuators.html">motor order and servo outputs</a>.</li></ul>',10)]))}const p=a(n,[["render",i]]);export{f as __pageData,p as default};
